package io.github.kjly.brna.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * More icons vendored directly from desktop Rnote's own symbolic icon set,
 * same rationale/source/license as [CustomIcons] — see that file's KDoc,
 * THIRD_PARTY_NOTICES.md, and LICENSE at the repo root.
 *
 * Several source SVGs (stroke-color, fill-color, pen-brush-style-*) contain a
 * decorative background dot-texture pattern (many tiny masked squares, an
 * Inkscape/GNOME icon-set convention) alongside the real glyph. Only the real
 * glyph's path(s) were extracted — identified because the decorative dots use
 * plain space-separated legacy path syntax while the real glyph is a modern
 * Inkscape export using comma-separated coordinates.
 */
object GeneratedIcons {

    private fun icon(name: String, vararg pathData: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 16f,
            viewportHeight = 16f
        ).apply {
            pathData.forEach { d ->
                addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
            }
        }.build()

    /**
     * As [icon], for the icons whose SVG draws part of the glyph at `fill-opacity="0.35"`
     * — the shaded area inside the selector styles' dashed outlines. Each path comes with
     * its opacity.
     */
    private fun shadedIcon(name: String, vararg paths: Pair<String, Float>): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 16f,
            viewportHeight = 16f
        ).apply {
            paths.forEach { (d, alpha) ->
                addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black), fillAlpha = alpha)
            }
        }.build()

